# Creates the AdventureWorks sample database in a PostgreSQL server:
#   1. downloads Microsoft's AdventureWorks OLTP data and the lorint PostgreSQL port, at pinned versions,
#      and checks their SHA-256;
#   2. converts the CSV files for PostgreSQL (the port's update_csvs.rb) and loads them (its install.sql);
#   3. applies this sample's changes (overlay.sql).
# The Dockerfile runs it while building the image. To use your own server instead, run it with psql's usual
# PGHOST, PGPORT, PGUSER and PGPASSWORD set for an account that can create databases and roles. Needs curl,
# unzip, ruby and psql.
set -euo pipefail

DB=${AW_DB_NAME:-adventureworks}
HERE=$(cd "$(dirname "$0")" && pwd)

DATA_URL=https://github.com/Microsoft/sql-server-samples/releases/download/adventureworks/AdventureWorks-oltp-install-script.zip
DATA_SHA256=58962e94ea386ef7cd3d8a08211bfd42a79d9b81bdd68fd4b6b0051de6c5bd42
PORT_COMMIT=b474991f0df1c4bf55ca4735eb0254ca0709eed2
PORT_URL=https://raw.githubusercontent.com/lorint/AdventureWorks-for-Postgres/$PORT_COMMIT
INSTALL_SHA256=27f71c99365aa5f44dba5d3b7ca092a654fcf50e6931c4dbe96ba2a13f8b7e0e
UPDATE_SHA256=f9c2575c21f1fc68ac9af655cb47d59ffbc1a85c1ae1b75312bb29994defa2b2

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
cd "$WORK"

echo "Downloading AdventureWorks data and the PostgreSQL port"
curl -fsSL -o data.zip "$DATA_URL"
curl -fsSL -o install.sql "$PORT_URL/install.sql"
curl -fsSL -o update_csvs.rb "$PORT_URL/update_csvs.rb"
sha256sum -c - <<SUMS
$DATA_SHA256  data.zip
$INSTALL_SHA256  install.sql
$UPDATE_SHA256  update_csvs.rb
SUMS

unzip -q data.zip '*.csv'
ruby update_csvs.rb > /dev/null

echo "Creating database $DB"
psql -v ON_ERROR_STOP=1 -q -d postgres -c "CREATE DATABASE \"$DB\""
psql -v ON_ERROR_STOP=1 -q -d "$DB" -f install.sql > /dev/null
psql -v ON_ERROR_STOP=1 -q -d "$DB" -f "$HERE/overlay.sql"
echo "AdventureWorks is ready in database $DB"
